import math
from typing import TypeVar, Generic, Union

T = TypeVar('T')

class Some(Generic[T]):
    def __init__(self, value: T):
        self.value = value

    def __repr__(self):
        return f"Some({self.value})"

    def __eq__(self, other):
        return isinstance(other, Some) and self.value == other.value

class Nothing:
    def __repr__(self):
        return "Nothing"

    def __eq__(self, other):
        return isinstance(other, Nothing)

NoneOption = Nothing() # Singleton for None equivalent

Option = Union[Some[T], Nothing]

def safeSqrt(n: float) -> Option[float]:
    if n >= 0:
        return Some(math.sqrt(n))
    else:
        return NoneOption

def main():
    # Test cases
    result1 = safeSqrt(16.0)
    result2 = safeSqrt(-4.0)

    # Print results
    if isinstance(result1, Some):
        print(f"Root: {result1.value}")
    else:
        print("Error: Negative input")

    if isinstance(result2, Some):
        print(f"Root: {result2.value}")
    else:
        print("Error: Negative input")

if __name__ == "__main__":
    main()

