def isBalanced(s: str) -> bool:
    """
    Checks if parentheses in a string are balanced using a counter.
    Increments for '(', decrements for ')'.
    """
    counter = 0
    for char in s:
        if char == '(':
            counter += 1
        elif char == ')':
            counter -= 1

        # If counter goes negative, a closing parenthesis appeared before an opening one
        if counter < 0:
            return False

    # Balanced only if counter ends exactly at zero
    return counter == 0

def main():
    test_cases = [
        "(())",
        "(()",
        "())()",
        "()(())"
    ]

    for case in test_cases:
        result = isBalanced(case)
        print("true" if result else "false")

if __name__ == "__main__":
    main()

