import std/result (Ok, Err)
import std/list (length, foldl)
import std/string (chars)

type Config = {app_name: string, version: string, port: int, features: [string]}

pure func countDots(s: string) -> int {
  let cs = chars(s);
  foldl(func(acc: int, c: string) -> int {
    if c == "." then acc + 1 else acc
  }, 0, cs)
}

pure func validPort(p: int) -> bool = p >= 1024 && p <= 65535

pure func validVersion(v: string) -> bool = countDots(v) == 2

pure func validFeatures(fs: [string]) -> bool = length(fs) > 0

func loadConfig(path: string) -> Option[Config] ! {FS} {
  let content = readFile(path);
  match decode(content) {
    Ok(obj) => {
      match getString(obj, "app_name") {
        Some(name) => {
          match getString(obj, "version") {
            Some(version) => {
              match getInt(obj, "port") {
                Some(port) => {
                  match getArray(obj, "features") {
                    Some(arr) => {
                      match allStrings(arr) {
                        Some(features) => {
                          if validPort(port) && validVersion(version) && validFeatures(features)
                          then Some({app_name: name, version: version, port: port, features: features})
                          else None
                        },
                        None => None
                      }
                    },
                    None => None
                  }
                },
                None => None
              }
            },
            None => None
          }
        },
        None => None
      }
    },
    Err(_) => None
  }
}

export func main() -> () ! {IO, FS} {
  let configJson = encode(jo([
    kv("app_name", js("MyApp")),
    kv("version", js("1.0.0")),
    kv("port", jnum(8080.0)),
    kv("features", ja([js("logging"), js("auth"), js("api")]))
  ]));
  writeFile("app_config.json", configJson);
  match loadConfig("app_config.json") {
    Some(cfg) => println("Loaded " ++ cfg.app_name ++ " v" ++ cfg.version ++ " on port " ++ show(cfg.port) ++ " with " ++ show(length(cfg.features)) ++ " features"),
    None => println("Invalid config")
  }
}

