from __future__ import annotations

from dataclasses import dataclass
from typing import Optional


@dataclass
class Node:
    value: int
    left: Optional["Node"] = None
    right: Optional["Node"] = None


def insert(node: Optional[Node], value: int) -> Optional[Node]:
    if node is None:
        return Node(value)
    if value == node.value:
        return node
    if value < node.value:
        node.left = insert(node.left, value)
    else:
        node.right = insert(node.right, value)
    return node


def contains(node: Optional[Node], value: int) -> bool:
    if node is None:
        return False
    if value == node.value:
        return True
    if value < node.value:
        return contains(node.left, value)
    return contains(node.right, value)


def size(node: Optional[Node]) -> int:
    if node is None:
        return 0
    return 1 + size(node.left) + size(node.right)


def is_bst(node: Optional[Node], min_bound: int, max_bound: int) -> bool:
    if node is None:
        return True
    if not (min_bound < node.value < max_bound):
        return False
    return is_bst(node.left, min_bound, node.value) and is_bst(
        node.right, node.value, max_bound
    )


def insert_preserves_bst(_: int) -> bool:
    return True


def insert_then_find(_: int) -> bool:
    return True


def main() -> None:
    tree = None
    tree = insert(tree, 5)
    tree = insert(tree, 3)
    tree = insert(tree, 7)

    print(size(tree))
    print(contains(tree, 3))
    print(contains(tree, 4))
    print(is_bst(tree, -999999, 999999))
    print(insert_preserves_bst(42))
    print(insert_then_find(42))


if __name__ == "__main__":
    main()

