import std/string (chars)

pure func repeatStr(s: string, n: int) -> string =
  if n <= 0 then "" else s ++ repeatStr(s, n - 1)

pure func encodeDigit(d: int, one: string, five: string, ten: string) -> string =
  if d == 0 then ""
  else if d == 1 then one
  else if d == 2 then one ++ one
  else if d == 3 then one ++ one ++ one
  else if d == 4 then one ++ five
  else if d == 5 then five
  else if d == 6 then five ++ one
  else if d == 7 then five ++ one ++ one
  else if d == 8 then five ++ one ++ one ++ one
  else if d == 9 then one ++ ten
  else ""

pure func toRoman(n: int) -> string {
  let thousands = n / 1000;
  let rem1 = n % 1000;
  let hundreds = rem1 / 100;
  let rem2 = rem1 % 100;
  let tens = rem2 / 10;
  let ones = rem2 % 10;
  repeatStr("M", thousands) ++ encodeDigit(hundreds, "C", "D", "M") ++ encodeDigit(tens, "X", "L", "C") ++ encodeDigit(ones, "I", "V", "X")
}

pure func romanCharVal(c: string) -> int =
  if c == "M" then 1000
  else if c == "D" then 500
  else if c == "C" then 100
  else if c == "L" then 50
  else if c == "X" then 10
  else if c == "V" then 5
  else if c == "I" then 1
  else 0

pure func sumRoman(cs: [string]) -> int =
  match cs {
    [] => 0,
    c1 :: rest => match rest {
      [] => romanCharVal(c1),
      c2 :: _ => {
        let v1 = romanCharVal(c1);
        let v2 = romanCharVal(c2);
        if v1 < v2 then (0 - v1) + sumRoman(rest)
        else v1 + sumRoman(rest)
      }
    }
  }

pure func fromRoman(s: string) -> int {
  let cs = chars(s);
  sumRoman(cs)
}

pure func roundtrip(n: int) -> bool {
  let roman = toRoman(n);
  let back = fromRoman(roman);
  back == n
}

pure func distinctEncoding(a: int, b: int) -> bool =
  if a == b then true
  else toRoman(a) != toRoman(b)

export func main() -> () ! {IO} {
  println(toRoman(1994));
  println(toRoman(58));
  println(toRoman(3999));
  println(show(fromRoman("MCMXCIV")));
  println(show(fromRoman("LVIII")));
  println(show(roundtrip(2024)));
  println(show(distinctEncoding(4, 6)))
}

