import sys

def toRoman(n: int) -> str:
    """Converts an integer (1-3999) to a Roman numeral string."""
    if not (0 < n < 4000):
        raise ValueError("Number must be between 1 and 3999")

    val_map = [
        (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
        (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
        (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I')
    ]

    result = []
    for val, sym in val_map:
        while n >= val:
            result.append(sym)
            n -= val

    return "".join(result)

def fromRoman(s: str) -> int:
    """Converts a Roman numeral string to an integer."""
    roman_map = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50,
        'C': 100, 'D': 500, 'M': 1000
    }

    total = 0
    prev_val = 0

    for char in reversed(s):
        val = roman_map.get(char, 0)
        if val < prev_val:
            total -= val
        else:
            total += val
        prev_val = val

    return total

def roundtrip(n: int) -> bool:
    """Verifies that converting to Roman and back returns the original number."""
    return fromRoman(toRoman(n)) == n

def distinctEncoding(a: int, b: int) -> bool:
    """Verifies that distinct integers produce distinct Roman numerals."""
    if a == b:
        return toRoman(a) == toRoman(b)
    return toRoman(a) != toRoman(b)

def main():
    print(toRoman(1994))
    print(toRoman(58))
    print(toRoman(3999))
    print(fromRoman("MCMXCIV"))
    print(fromRoman("LVIII"))
    print(roundtrip(2024))
    print(distinctEncoding(4, 6))

if __name__ == "__main__":
    main()

