module benchmark/solution

type SSet = SNil | SCons(int, SSet)

pure func sLength(s: SSet) -> int =
  match s {
    SNil => 0,
    SCons(_, rest) => 1 + sLength(rest)
  }

pure func isSortedFrom(prev: int, s: SSet) -> bool =
  match s {
    SNil => true,
    SCons(x, rest) => x > prev && isSortedFrom(x, rest)
  }

pure func isSorted(s: SSet) -> bool =
  match s {
    SNil => true,
    SCons(x, rest) => isSortedFrom(x, rest)
  }

pure func sMerge(a: SSet, b: SSet) -> SSet =
  match a {
    SNil => b,
    SCons(x, xs) => match b {
      SNil => a,
      SCons(y, ys) =>
        if x < y then SCons(x, sMerge(xs, b))
        else if x > y then SCons(y, sMerge(a, ys))
        else SCons(x, sMerge(xs, ys))
    }
  }

pure func sIntersect(a: SSet, b: SSet) -> SSet =
  match a {
    SNil => SNil,
    SCons(x, xs) => match b {
      SNil => SNil,
      SCons(y, ys) =>
        if x < y then sIntersect(xs, b)
        else if x > y then sIntersect(a, ys)
        else SCons(x, sIntersect(xs, ys))
    }
  }

pure func toStrTail(s: SSet) -> string =
  match s {
    SNil => "",
    SCons(x, rest) => "," ++ show(x) ++ toStrTail(rest)
  }

pure func toStr(s: SSet) -> string =
  match s {
    SNil => "[]",
    SCons(x, rest) => "[" ++ show(x) ++ toStrTail(rest) ++ "]"
  }

export func mergePreservesSorted(a: SSet, b: SSet) -> bool ! {}
ensures { result == (if isSorted(a) && isSorted(b) then isSorted(sMerge(a, b)) else true) }
{
  if isSorted(a) && isSorted(b) then isSorted(sMerge(a, b)) else true
}

export func inclusionExclusion(a: SSet, b: SSet) -> bool ! {}
ensures { result == (if isSorted(a) && isSorted(b) then sLength(sMerge(a, b)) + sLength(sIntersect(a, b)) == sLength(a) + sLength(b) else true) }
{
  if isSorted(a) && isSorted(b) then sLength(sMerge(a, b)) + sLength(sIntersect(a, b)) == sLength(a) + sLength(b) else true
}

export func main() -> () ! {IO} {
  let a = SCons(1, SCons(3, SCons(5, SNil)));
  let b = SCons(2, SCons(3, SCons(4, SNil)));
  println(toStr(sMerge(a, b)));
  println(toStr(sIntersect(a, b)));
  println(show(sLength(sMerge(a, b))));
  println(show(isSorted(sMerge(a, b))));
  println(show(mergePreservesSorted(a, b)));
  println(show(inclusionExclusion(a, b)))
