import sys

class SortedSet:
    """Base class for the Sorted Integer Set ADT."""
    pass

class SNilClass(SortedSet):
    """Represents an empty set (Singleton)."""
    def __repr__(self):
        return "SNil"

# Singleton instance for Empty Set
SNil = SNilClass()

class SCons(SortedSet):
