from __future__ import annotations
from abc import ABC, abstractmethod
from typing import Generic, TypeVar, Callable

T = TypeVar("T")
U = TypeVar("U")

class Result(ABC, Generic[T]):
    """Abstract base class for Result type."""

    @abstractmethod
    def and_then(self, func: Callable[[T], Result[U]]) -> Result[U]:
        """Chains operations if the result is Ok."""
        pass

class Ok(Result[T]):
    """Variant representing a successful result."""

    def __init__(self, value: T):
        self.value = value

    def and_then(self, func: Callable[[T], Result[U]]) -> Result[U]:
        return func(self.value)

class Err(Result[T]):
    """Variant representing a failure result."""

    def __init__(self, message: str):
        self.message = message

    def and_then(self, func: Callable[[T], Result[U]]) -> Result[U]:
        # Propagate the error, effectively casting to the new type
        return Err(self.message)

def validate_age(age: int) -> Result[int]:
    """Validates if age is within the acceptable range [0, 150]."""
    if 0 <= age <= 150:
        return Ok(age)
    return Err("Age out of range")

def calculate_retirement_years(age: int) -> Result[int]:
    """Calculates years remaining until retirement at age 65."""
    if age < 65:
        return Ok(65 - age)
    return Err("Already retired")

def main():
    test_cases = [30, 70, -5]

    for age in test_cases:
        # Chain operations: validate -> calculate
        result = validate_age(age).and_then(calculate_retirement_years)

        # Print final result based on variant
        if isinstance(result, Ok):
            print(f"Years to retirement: {result.value}")
        elif isinstance(result, Err):
            print(f"Error: {result.message}")

if __name__ == "__main__":
    main()

