from abc import ABC
from dataclasses import dataclass

class Expr(ABC):
    """Abstract base class for expression AST nodes."""
    pass

@dataclass
class Num(Expr):
    """Represents a numeric literal."""
    value: int

@dataclass
class Add(Expr):
    """Represents addition of two expressions."""
    left: Expr
    right: Expr

@dataclass
class Mul(Expr):
    """Represents multiplication of two expressions."""
    left: Expr
    right: Expr

def eval_expr(expr: Expr) -> int:
    """Evaluates an expression AST to an integer."""
    if isinstance(expr, Num):
        return expr.value
    elif isinstance(expr, Add):
        return eval_expr(expr.left) + eval_expr(expr.right)
    elif isinstance(expr, Mul):
        return eval_expr(expr.left) * eval_expr(expr.right)
    else:
        raise TypeError(f"Unknown expression type: {type(expr).__name__}")

def main() -> None:
    # Construct the AST for: (3 + 4) * (2 + 5)
    # Tree: Mul(Add(Num(3), Num(4)), Add(Num(2), Num(5)))
    expression = Mul(
        Add(Num(3), Num(4)),
        Add(Num(2), Num(5))
    )

    result = eval_expr(expression)
    print(result)

