pure func contains(x: int, xs: [int]) -> bool =
  match xs {
    [] => false,
    y :: rest => if x == y then true else contains(x, rest)
  }

pure func enqueue(x: int, queue: [int]) -> [int] =
  match queue {
    [] => [x],
    y :: rest => y :: enqueue(x, rest)
  }

pure func enqueueAll(xs: [int], queue: [int]) -> [int] =
  match xs {
    [] => queue,
    x :: rest => enqueueAll(rest, enqueue(x, queue))
  }

pure func neighborsOf(node: int, graph: [(int, [int])]) -> [int] =
  match graph {
    [] => [],
    entry :: rest => match entry {
      (n, neighbors) => if node == n then neighbors else neighborsOf(node, rest)
    }
  }

pure func bfsLoop(graph: [(int, [int])], queue: [int], visited: [int], order: [int]) -> [int] =
  match queue {
    [] => order,
    current :: rest =>
      if contains(current, visited) then bfsLoop(graph, rest, visited, order)
      else {
        let neighbors = neighborsOf(current, graph);
        let newQueue = enqueueAll(neighbors, rest);
        let newVisited = enqueue(current, visited);
        let newOrder = enqueue(current, order);
        bfsLoop(graph, newQueue, newVisited, newOrder)
      }
  }

pure func bfs(graph: [(int, [int])], start: int) -> [int] =
  bfsLoop(graph, [start], [], [])

