from dataclasses import dataclass

class Term:
    pass

@dataclass
class TVar(Term):
    name: str

    def __repr__(self):
        return f'TVar("{self.name}")'

@dataclass
class TLam(Term):
    var: str
    body: Term

    def __repr__(self):
        return f'TLam("{self.var}", {repr(self.body)})'

@dataclass
class TApp(Term):
    func: Term
    arg: Term

    def __repr__(self):
        return f'TApp({repr(self.func)}, {repr(self.arg)})'

def subst(term: Term, var: str, replacement: Term) -> Term:
    if isinstance(term, TVar):
        if term.name == var:
            return replacement
        return term
    elif isinstance(term, TLam):
        if term.var == var:
            return term
        return TLam(term.var, subst(term.body, var, replacement))
    elif isinstance(term, TApp):
        return TApp(
            subst(term.func, var, replacement),
            subst(term.arg, var, replacement)
        )
    return term

def eval(term: Term) -> Term:
    if isinstance(term, TVar):
        return term
    elif isinstance(term, TLam):
        return term
    elif isinstance(term, TApp):
        f = eval(term.func)
        arg = eval(term.arg)
        if isinstance(f, TLam):
            return eval(subst(f.body, f.var, arg))
        return TApp(f, arg)
    return term

def main():
    expr = TApp(
        TApp(
            TLam("x", TLam("y", TVar("x"))),
            TVar("1")
        ),
        TVar("2")
    )
    result = eval(expr)
    print(result)

if __name__ == "__main__":
    main()

