from dataclasses import dataclass
from typing import List, Tuple, Union

# Define the AST
@dataclass
class Expr:
    pass

@dataclass
class Num(Expr):
    value: int

@dataclass
class Var(Expr):
    name: str

@dataclass
class Add(Expr):
    left: Expr
    right: Expr

@dataclass
class Mul(Expr):
    left: Expr
    right: Expr

@dataclass
class Let(Expr):
    name: str
    value_expr: Expr
    body_expr: Expr

# Define the environment type
Env = List[Tuple[str, int]]

def lookup(name: str, env: Env) -> int:
    """
    Find a variable's value in the environment.
    Scans from the end of the list to find the most recent binding (shadowing).
    """
    for var_name, value in reversed(env):
        if var_name == name:
            return value
    raise ValueError(f"Variable '{name}' not found in environment")

def evaluate(expr: Expr, env: Env) -> int:
    """
    Evaluates an expression in a given environment.
    """
    if isinstance(expr, Num):
        return expr.value

    elif isinstance(expr, Var):
        return lookup(expr.name, env)

    elif isinstance(expr, Add):
        return evaluate(expr.left, env) + evaluate(expr.right, env)

    elif isinstance(expr, Mul):
        return evaluate(expr.left, env) * evaluate(expr.right, env)

    elif isinstance(expr, Let):
        # Evaluate the bound value in the current environment
        bound_val = evaluate(expr.value_expr, env)
        # Extend the environment (create a new scope)
        new_env = env + [(expr.name, bound_val)]
        # Evaluate the body in the new environment
        return evaluate(expr.body_expr, new_env)

    else:
        raise TypeError(f"Unknown expression type: {type(expr)}")

def main() -> None:
    # Program:
    # let x = 5 in
    #   let y = x + 3 in
    #     x * y

    program = Let(
        "x", 
        Num(5), 
        Let(
            "y", 
            Add(Var("x"), Num(3)), 
            Mul(Var("x"), Var("y"))
        )
    )

    try:
        # Start with an empty environment
        initial_env: Env = []
        result = evaluate(program, initial_env)
        print(result)
    except Exception as e:
        print(f"Error evaluating program: {e}")

if __name__ == "__main__":
    main()

