from typing import TypeVar, Generic, Union, Sequence, Callable, Any

T = TypeVar("T")
U = TypeVar("U")

class Some(Generic[T]):
    def __init__(self, value: T):
        self.value = value

    def __repr__(self):
        return f"Some({self.value})"

class OptionNone:
    def __repr__(self):
        return "None"

# Singleton instance for None case
Nothing = OptionNone()
Option = Union[Some[T], OptionNone]

def safeLast(lst: Sequence[T]) -> Option[T]:
    if not lst:
        return Nothing
    return Some(lst[-1])

def safeHead(lst: Sequence[T]) -> Option[T]:
    if not lst:
        return Nothing
    return Some(lst[0])

def flatMapOption(fn: Callable[[T], Option[U]], opt: Option[T]) -> Option[U]:
    if isinstance(opt, Some):
        return fn(opt.value)
    return Nothing

def run_test(data: list[str]) -> None:
    # 1. Get last element safely
    last_opt = safeLast(data)

    # 2. FlatMap safeHead over the string (sequence of chars)
    # The lambda takes the string inside the Some and applies safeHead to it
    result = flatMapOption(lambda s: safeHead(s), last_opt)

    # 3. Handle output pattern matching style
    if isinstance(result, Some):
        print(f"Last starts with: {result.value}")
    else:
        print("Empty list")

