from dataclasses import dataclass
from typing import Union

@dataclass
class Leaf:
    value: int

@dataclass
class Node:
    left: "Tree"
    value: int
    right: "Tree"

# Define Tree Type as a Union of Leaf and Node
Tree = Union[Leaf, Node]

def tree_sum(tree: Tree) -> int:
    """Calculates the sum of all values in the tree using type dispatching."""
    if isinstance(tree, Leaf):
        return tree.value
    elif isinstance(tree, Node):
        return tree_sum(tree.left) + tree.value + tree_sum(tree.right)
    else:
        raise TypeError(f"Expected Tree, got {type(tree)}")

def find_max(tree: Tree) -> int:
    """Finds the maximum value in the tree using type dispatching."""
    if isinstance(tree, Leaf):
        return tree.value
    elif isinstance(tree, Node):
        # Logic equivalent to matching Node(l, v, r) and finding max
        left_max = find_max(tree.left)
        right_max = find_max(tree.right)
        return max(left_max, tree.value, right_max)
    else:
        raise TypeError(f"Expected Tree, got {type(tree)}")

