from dataclasses import dataclass
from typing import Union

# --- State Definitions ---

@dataclass
class Idle:
    floor: int

@dataclass
class Moving:
    current_floor: int
    target_floor: int

@dataclass
class DoorOpen:
    floor: int
    timer: int

# Type alias for state
ElevatorState = Union[Idle, Moving, DoorOpen]

# --- Event Definitions ---

@dataclass
class Call:
    floor: int

@dataclass
class Tick:
    pass

@dataclass
class Arrive:
    pass

# Type alias for event
ElevatorEvent = Union[Call, Tick, Arrive]

# --- Core Logic ---

def transition(state: ElevatorState, event: ElevatorEvent) -> ElevatorState:
    """
    Determines the next state based on the current state and the event.
    Uses isinstance checks to simulate pattern matching for Python compatibility.
    """

    # State: Idle(floor)
    if isinstance(state, Idle):
        if isinstance(event, Call):
            # Idle(floor) + Call(target)
            if event.floor == state.floor:
                return DoorOpen(state.floor, 3)
            return Moving(state.floor, event.floor)

    # State: Moving(current_floor, target_floor)
    elif isinstance(state, Moving):
        if isinstance(event, Tick):
            # Moving + Tick
            return state
        elif isinstance(event, Arrive):
            # Moving + Arrive
            return DoorOpen(state.target_floor, 3)

    # State: DoorOpen(floor, timer)
    elif isinstance(state, DoorOpen):
        if isinstance(event, Tick):
            # DoorOpen + Tick
            if state.timer > 1:
                return DoorOpen(state.floor, state.timer - 1)
            return Idle(state.floor)

    # Default: Return current state unchanged
    return state

def format_state(state: ElevatorState) -> str:
    """
    Returns the string representation of the state.
    """
    if isinstance(state, Idle):
        return f"IDLE @ floor {state.floor}"
    elif isinstance(state, Moving):
        return f"MOVING {state.current_floor} -> {state.target_floor}"
    elif isinstance(state, DoorOpen):
        return f"DOOR_OPEN @ floor {state.floor} ({state.timer}sec)"
    else:
        return "UNKNOWN STATE"

# --- Main Simulation ---

def main():
    # Start with Idle(1)
    state: ElevatorState = Idle(1)

    # Define sequence of events
    events = []

    # Apply Call(5)
    events.append(Call(5))

    # Apply 2 Tick events
    events.append(Tick())
    events.append(Tick())

    # Apply Arrive event
    events.append(Arrive())

    # Apply 4 Tick events
    events.append(Tick())
    events.append(Tick())
    events.append(Tick())
    events.append(Tick())

    # Apply Call(1) event
    events.append(Call(1))

    # Process events
    for event in events:
        state = transition(state, event)
        print(format_state(state))

if __name__ == "__main__":
    main()

