from dataclasses import dataclass
from typing import Union


@dataclass
class Const:
    value: int


@dataclass
class Var:
    name: str


@dataclass
class Add:
    left: 'Expr'
    right: 'Expr'


@dataclass
class Mul:
    left: 'Expr'
    right: 'Expr'


Expr = Union[Const, Var, Add, Mul]


def diff(expr, var):
    if isinstance(expr, Const):
        return Const(0)
    elif isinstance(expr, Var):
        return Const(1) if expr.name == var else Const(0)
    elif isinstance(expr, Add):
        return Add(diff(expr.left, var), diff(expr.right, var))
    elif isinstance(expr, Mul):
        return Add(Mul(expr.left, diff(expr.right, var)), Mul(expr.right, diff(expr.left, var)))


def simplify(expr):
    if isinstance(expr, (Const, Var)):
        return expr
    elif isinstance(expr, Add):
        sl = simplify(expr.left)
        sr = simplify(expr.right)
        if isinstance(sl, Const) and sl.value == 0:
            return sr
        if isinstance(sr, Const) and sr.value == 0:
            return sl
        if isinstance(sl, Const) and isinstance(sr, Const):
            return Const(sl.value + sr.value)
        return Add(sl, sr)
    elif isinstance(expr, Mul):
        sl = simplify(expr.left)
        sr = simplify(expr.right)
        if isinstance(sl, Const) and sl.value == 0:
            return Const(0)
        if isinstance(sr, Const) and sr.value == 0:
            return Const(0)
        if isinstance(sl, Const) and sl.value == 1:
            return sr
        if isinstance(sr, Const) and sr.value == 1:
            return sl
        if isinstance(sl, Const) and isinstance(sr, Const):
            return Const(sl.value * sr.value)
        return Mul(sl, sr)


def show_expr(expr):
    if isinstance(expr, Const):
        return str(expr.value)
    elif isinstance(expr, Var):
        return expr.name
    elif isinstance(expr, Add):
        return "(" + show_expr(expr.left) + " + " + show_expr(expr.right) + ")"
    elif isinstance(expr, Mul):
        return "(" + show_expr(expr.left) + " * " + show_expr(expr.right) + ")"


def main():
    expr = Add(
        Add(
            Mul(Var("x"), Var("x")),
            Mul(Const(3), Var("x"))
        ),
        Const(5)
    )

    derivative = diff(expr, "x")
    simplified = simplify(derivative)
    print(show_expr(simplified))


if __name__ == "__main__":
    main()

