from abc import ABC
from dataclasses import dataclass
from typing import Callable, List, TypeVar, Any

T = TypeVar("T")

class Tree(ABC):
    """Abstract base class for Tree structure."""
    pass

@dataclass
class Leaf(Tree):
    """A leaf node containing a single integer value."""
    value: int

@dataclass
class Node(Tree):
    """An internal node containing left subtree, value, and right subtree."""
    left: Tree
    value: int
    right: Tree

def mapTree(fn: Callable[[int], int], tree: Tree) -> Tree:
    """Recursively applies a function to all values in the tree."""
    if isinstance(tree, Leaf):
        return Leaf(fn(tree.value))
    elif isinstance(tree, Node):
        return Node(
            mapTree(fn, tree.left),
            fn(tree.value),
            mapTree(fn, tree.right)
        )
    raise TypeError(f"Unknown tree type: {type(tree)}")

def foldTree(fn: Callable[[T, int], T], acc: T, tree: Tree) -> T:
    """Performs an in-order fold over tree values."""
    if isinstance(tree, Leaf):
        return fn(acc, tree.value)
    elif isinstance(tree, Node):
        acc = foldTree(fn, acc, tree.left)
        acc = fn(acc, tree.value)
        return foldTree(fn, acc, tree.right)
    raise TypeError(f"Unknown tree type: {type(tree)}")

def treeToList(tree: Tree) -> List[int]:
    """Returns a list of integers from an in-order traversal."""
    if isinstance(tree, Leaf):
        return [tree.value]
    elif isinstance(tree, Node):
        return treeToList(tree.left) + [tree.value] + treeToList(tree.right)
    raise TypeError(f"Unknown tree type: {type(tree)}")

def treeDepth(tree: Tree) -> int:
    """Returns maximum depth of tree (Leaf has depth 1)."""
    if isinstance(tree, Leaf):
        return 1
    elif isinstance(tree, Node):
        return 1 + max(treeDepth(tree.left), treeDepth(tree.right))
    raise TypeError(f"Unknown tree type: {type(tree)}")

def double(x: int) -> int:
    """Doubles an integer value."""
    return x * 2

def add(acc: int, x: int) -> int:
    """Adds a value to the accumulator."""
    return acc + x

def main() -> None:
    # Construct the tree structure:
    #       4
    #      / \
    #     2   6
    #    / \ / \
    #   1  3 5  7
    # Node(Node(Leaf(1), 2, Leaf(3)), 4, Node(Leaf(5), 6, Leaf(7)))
    tree = Node(
        Node(Leaf(1), 2, Leaf(3)),
        4,
        Node(Leaf(5), 6, Leaf(7))
    )

    # 1. treeToList(tree)
    result_list = treeToList(tree)
    print(f"treeToList(tree): {result_list}")

    # 2. treeToList(mapTree(double, tree))
    mapped_tree = mapTree(double, tree)
    mapped_list = treeToList(mapped_tree)
    print(f"treeToList(mapTree(double, tree)): {mapped_list}")

    # 3. foldTree(add, 0, tree)
    folded_result = foldTree(add, 0, tree)
    print(f"foldTree(add, 0, tree): {folded_result}")

    # 4. treeDepth(tree)
    depth = treeDepth(tree)
    print(f"treeDepth(tree): {depth}")

if __name__ == "__main__":
    main()

