from dataclasses import dataclass
from typing import List, Tuple

class Type:
    pass

@dataclass(frozen=True)
class TVar(Type):
    name: str

    def __str__(self) -> str:
        return f"TVar({self.name})"

@dataclass(frozen=True)
class TInt(Type):
    def __str__(self) -> str:
        return "TInt"

@dataclass(frozen=True)
class TBool(Type):
    def __str__(self) -> str:
        return "TBool"

@dataclass(frozen=True)
class TFunc(Type):
    arg: Type
    res: Type

    def __str__(self) -> str:
        return f"TFunc({self.arg}, {self.res})"

Subst = List[Tuple[str, Type]]

def apply(subst: Subst, t: Type) -> Type:
    if isinstance(t, TVar):
        for k, v in subst:
            if k == t.name:
                return v
        return t
    elif isinstance(t, TFunc):
        return TFunc(apply(subst, t.arg), apply(subst, t.res))
    return t

def unify(t1: Type, t2: Type) -> Subst:
    if isinstance(t1, TInt) and isinstance(t2, TInt):
        return []
    if isinstance(t1, TBool) and isinstance(t2, TBool):
        return []
    if isinstance(t1, TVar):
        if isinstance(t2, TVar) and t1.name == t2.name:
            return []
        return [(t1.name, t2)]
    if isinstance(t2, TVar):
        return [(t2.name, t1)]
    if isinstance(t1, TFunc) and isinstance(t2, TFunc):
        s1 = unify(t1.arg, t2.arg)
        s2 = unify(apply(s1, t1.res), apply(s1, t2.res))
        return [(k, apply(s2, v)) for k, v in s1] + s2

    raise ValueError("fail")

def main() -> None:
    t1 = TFunc(TVar("a"), TInt())
    t2 = TFunc(TBool(), TVar("b"))

    try:
        subst = unify(t1, t2)
        for k, v in subst:
            print(f"{k} = {v}")
    except ValueError:
        print("Types do not unify.")

if __name__ == "__main__":
    main()
